package com.dlt.predictor.config;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig{@Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/actuator/**","/api/v1/auth/**","/api/v1/dlt/draws/**").permitAll().anyRequest().permitAll()).build();}}
